    /// Specifies the steps (actions) to take if errors are encountered during execution of the workflow. NOTE: For custom steps, the Lambda function needs to send FAILURE to the call back API to kick off the exception steps. Additionally, if the Lambda does not send SUCCESS before it times out, the exception steps are executed. Constraints: • min: 0 • max: 8 (structure) The basic building block of a workflow. Type -&gt; (string) Currently, the following step types are supported. o ** COPY ** - Copy the file to another location. System Message: WARNING/2 (&lt;string&gt;:, line 1190) Inline strong start-string without end-string. o ** CUSTOM ** - Perform a custom step with an Lambda function target. System Message: WARNING/2 (&lt;string&gt;:, line 1192) Inline strong start-string without end-string. o ** DECRYPT ** - Decrypt a file that was encrypted before it was uploaded. System Message: WARNING/2 (&lt;string&gt;:, line 1194) Inline strong start-string without end-string. o ** DELETE ** - Delete the file. System Message: WARNING/2 (&lt;string&gt;:, line 1196) Inline strong start-string without end-string. o ** TAG ** - Add a tag to the file. System Message: WARNING/2 (&lt;string&gt;:, line 1198) Inline strong start-string without end-string. Possible values: • COPY • CUSTOM • TAG • DELETE • DECRYPT CopyStepDetails -&gt; (structure) Details for a step that performs a file copy. Consists of the following values: • A description • An Amazon S3 location for the destination of the file copy. • A flag that indicates whether to overwrite an existing file of the same name. The default is FALSE . Name -&gt; (string) The name of the step, used as an identifier. Constraints: • min: 0 • max: 30 • pattern: [\w-]* DestinationFileLocation -&gt; (structure) Specifies the location for the file being copied. Use ${Transfer:UserName} or ${Transfer:UploadDate} in this field to parametrize the destination prefix by username or uploaded date. • Set the value of DestinationFileLocation to ${Transfer:UserName} to copy uploaded files to an Amazon S3 bucket that is prefixed with the name of the Transfer Family user that uploaded the file. • Set the value of DestinationFileLocation to ${Transfer:UploadDate} to copy uploaded files to an Amazon S3 bucket that is prefixed with the date of the upload. NOTE: The system resolves UploadDate to a date format of YYYY-MM-DD , based on the date the file is uploaded in UTC. S3FileLocation -&gt; (structure) Specifies the details for the Amazon S3 file that's being copied or decrypted. Bucket -&gt; (string) Specifies the S3 bucket for the customer input file. Constraints: • min: 3 • max: 63 • pattern: [a-z0-9][\.\-a-z0-9]{1,61}[a-z0-9] Key -&gt; (string) The name assigned to the file when it was created in Amazon S3. You use the object key to retrieve the object. Constraints: • min: 0 • max: 1024 • pattern: [\P{M}\p{M}]* EfsFileLocation -&gt; (structure) Specifies the details for the Amazon Elastic File System (Amazon EFS) file that's being decrypted. FileSystemId -&gt; (string) The identifier of the file system, assigned by Amazon EFS. Constraints: • min: 0 • max: 128 • pattern: (arn:aws[-a-z]*:elasticfilesystem:[0-9a-z-:]+:(access-point/fsap|file-system/fs)-[0-9a-f]{8,40}|fs(ap)?-[0-9a-f]{8,40}) Path -&gt; (string) The pathname for the folder being used by a workflow. Constraints: • min: 1 • max: 65536 • pattern: [^\x00]+ OverwriteExisting -&gt; (string) A flag that indicates whether to overwrite an existing file of the same name. The default is FALSE . If the workflow is processing a file that has the same name as an existing file, the behavior is as follows: • If OverwriteExisting is TRUE , the existing file is replaced with the file being processed. • If OverwriteExisting is FALSE , nothing happens, and the workflow processing stops. Possible values: • TRUE • FALSE SourceFileLocation -&gt; (string) Specifies which file to use as input to the workflow step: either the output from the previous step, or the originally uploaded file for the workflow. • To use the previous file as the input, enter ${previous.file} . In this case, this workflow step uses the output file from the previous workflow step as input. This is the default value. • To use the originally uploaded file location as input for this step, enter ${original.file} . Constraints: • min: 0 • max: 256 • pattern: \$\{(\w+.)+\w+\} CustomStepDetails -&gt; (structure) Details for a step that invokes an Lambda function. Consists of the Lambda function's name, target, and timeout (in seconds). Name -&gt; (string) The name of the step, used as an identifier. Constraints: • min: 0 • max: 30 • pattern: [\w-]* Target -&gt; (string) The ARN for the Lambda function that is being called. Constraints: • min: 0 • max: 170 • pattern: arn:[a-z-]+:lambda:.* TimeoutSeconds -&gt; (integer) Timeout, in seconds, for the step. Constraints: • min: 1 • max: 1800 SourceFileLocation -&gt; (string) Specifies which file to use as input to the workflow step: either the output from the previous step, or the originally uploaded file for the workflow. • To use the previous file as the input, enter ${previous.file} . In this case, this workflow step uses the output file from the previous workflow step as input. This is the default value. • To use the originally uploaded file location as input for this step, enter ${original.file} . Constraints: • min: 0 • max: 256 • pattern: \$\{(\w+.)+\w+\} DeleteStepDetails -&gt; (structure) Details for a step that deletes the file. Name -&gt; (string) The name of the step, used as an identifier. Constraints: • min: 0 • max: 30 • pattern: [\w-]* SourceFileLocation -&gt; (string) Specifies which file to use as input to the workflow step: either the output from the previous step, or the originally uploaded file for the workflow. • To use the previous file as the input, enter ${previous.file} . In this case, this workflow step uses the output file from the previous workflow step as input. This is the default value. • To use the originally uploaded file location as input for this step, enter ${original.file} . Constraints: • min: 0 • max: 256 • pattern: \$\{(\w+.)+\w+\} TagStepDetails -&gt; (structure) Details for a step that creates one or more tags. You specify one or more tags. Each tag contains a key-value pair. Name -&gt; (string) The name of the step, used as an identifier. Constraints: • min: 0 • max: 30 • pattern: [\w-]* Tags -&gt; (list) Array that contains from 1 to 10 key/value pairs. Constraints: • min: 1 • max: 10 (structure) Specifies the key-value pair that are assigned to a file during the execution of a Tagging step. Key -&gt; (string) [required] The name assigned to the tag that you create. Constraints: • min: 1 • max: 128 • pattern: ([\p{L}\p{Z}\p{N}_.:/=+\-@]*) Value -&gt; (string) [required] The value that corresponds to the key. Constraints: • min: 0 • max: 256 • pattern: ([\p{L}\p{Z}\p{N}_.:/=+\-@]*) SourceFileLocation -&gt; (string) Specifies which file to use as input to the workflow step: either the output from the previous step, or the originally uploaded file for the workflow. • To use the previous file as the input, enter ${previous.file} . In this case, this workflow step uses the output file from the previous workflow step as input. This is the default value. • To use the originally uploaded file location as input for this step, enter ${original.file} . Constraints: • min: 0 • max: 256 • pattern: \$\{(\w+.)+\w+\} DecryptStepDetails -&gt; (structure) Details for a step that decrypts an encrypted file. Consists of the following values: • A descriptive name • An Amazon S3 or Amazon Elastic File System (Amazon EFS) location for the source file to decrypt. • An S3 or Amazon EFS location for the destination of the file decryption. • A flag that indicates whether to overwrite an existing file of the same name. The default is FALSE . • The type of encryption that's used. Currently, only PGP encryption is supported. Name -&gt; (string) The name of the step, used as an identifier. Constraints: • min: 0 • max: 30 • pattern: [\w-]* Type -&gt; (string) [required] The type of encryption used. Currently, this value must be PGP . Possible values: • PGP SourceFileLocation -&gt; (string) Specifies which file to use as input to the workflow step: either the output from the previous step, or the originally uploaded file for the workflow. • To use the previous file as the input, enter ${previous.file} . In this case, this workflow step uses the output file from the previous workflow step as input. This is the default value. • To use the originally uploaded file location as input for this step, enter ${original.file} . Constraints: • min: 0 • max: 256 • pattern: \$\{(\w+.)+\w+\} OverwriteExisting -&gt; (string) A flag that indicates whether to overwrite an existing file of the same name. The default is FALSE . If the workflow is processing a file that has the same name as an existing file, the behavior is as follows: • If OverwriteExisting is TRUE , the existing file is replaced with the file being processed. • If OverwriteExisting is FALSE , nothing happens, and the workflow processing stops. Possible values: • TRUE • FALSE DestinationFileLocation -&gt; (structure) [required] Specifies the location for the file being decrypted. Use ${Transfer:UserName} or ${Transfer:UploadDate} in this field to parametrize the destination prefix by username or uploaded date. • Set the value of DestinationFileLocation to ${Transfer:UserName} to decrypt uploaded files to an Amazon S3 bucket that is prefixed with the name of the Transfer Family user that uploaded the file. • Set the value of DestinationFileLocation to ${Transfer:UploadDate} to decrypt uploaded files to an Amazon S3 bucket that is prefixed with the date of the upload. NOTE: The system resolves UploadDate to a date format of YYYY-MM-DD , based on the date the file is uploaded in UTC. S3FileLocation -&gt; (structure) Specifies the details for the Amazon S3 file that's being copied or decrypted. Bucket -&gt; (string) Specifies the S3 bucket for the customer input file. Constraints: • min: 3 • max: 63 • pattern: [a-z0-9][\.\-a-z0-9]{1,61}[a-z0-9] Key -&gt; (string) The name assigned to the file when it was created in Amazon S3. You use the object key to retrieve the object. Constraints: • min: 0 • max: 1024 • pattern: [\P{M}\p{M}]* EfsFileLocation -&gt; (structure) Specifies the details for the Amazon Elastic File System (Amazon EFS) file that's being decrypted. FileSystemId -&gt; (string) The identifier of the file system, assigned by Amazon EFS. Constraints: • min: 0 • max: 128 • pattern: (arn:aws[-a-z]*:elasticfilesystem:[0-9a-z-:]+:(access-point/fsap|file-system/fs)-[0-9a-f]{8,40}|fs(ap)?-[0-9a-f]{8,40}) Path -&gt; (string) The pathname for the folder being used by a workflow. Constraints: • min: 1 • max: 65536 • pattern: [^\x00]+ JSON Syntax: [ { "Type": "COPY"|"CUSTOM"|"TAG"|"DELETE"|"DECRYPT", "CopyStepDetails": { "Name": "string", "DestinationFileLocation": { "S3FileLocation": { "Bucket": "string", "Key": "string" }, "EfsFileLocation": { "FileSystemId": "string", "Path": "string" } }, "OverwriteExisting": "TRUE"|"FALSE", "SourceFileLocation": "string" }, "CustomStepDetails": { "Name": "string", "Target": "string", "TimeoutSeconds": integer, "SourceFileLocation": "string" }, "DeleteStepDetails": { "Name": "string", "SourceFileLocation": "string" }, "TagStepDetails": { "Name": "string", "Tags": [ { "Key": "string", "Value": "string" } ... ], "SourceFileLocation": "string" }, "DecryptStepDetails": { "Name": "string", "Type": "PGP", "SourceFileLocation": "string", "OverwriteExisting": "TRUE"|"FALSE", "DestinationFileLocation": { "S3FileLocation": { "Bucket": "string", "Key": "string" }, "EfsFileLocation": { "FileSystemId": "string", "Path": "string" } } } } ... ]
    /// </summary>
    [CliOption("--on-exception-steps", GroupValues = true)]
    public IEnumerable<string>? OnExceptionSteps { get; set; }

    /// <summary>
    /// Key-value pairs that can be used to group and search for workflows. Tags are metadata attached to workflows for any purpose. Constraints: • min: 1 • max: 50 (structure) Creates a key-value pair for a specific resource. Tags are metadata that you can use to search for and group a resource for various purposes. You can apply tags to servers, users, and roles. A tag key can take more than one value. For example, to group servers for accounting purposes, you might create a tag called Group and assign the values Research and Accounting to that group. Key -&gt; (string) [required] The name assigned to the tag that you create. Constraints: • min: 0 • max: 128 Value -&gt; (string) [required] Contains one or more values that you assigned to the key name you create. Constraints: • min: 0 • max: 256 Shorthand Syntax: Key=string,Value=string ... JSON Syntax: [ { "Key": "string", "Value": "string" } ... ]
    /// </summary>
    [CliOption("--tags", GroupValues = true)]
    public IEnumerable<string>? Tags { get; set; }

    /// <summary>
    /// Specifies the log groups to which your workflow logs are sent. To specify a log group, you must provide the ARN for an existing log group. In this case, the format of the log group is as follows: arn:partition:logs:region-name:amazon-account-id:log-group:log-group-name:* For example, arn:aws:logs:us-east-1:111122223333:log-group:mytestgroup:* Constraints: • min: 0 • max: 1 (string) Constraints: • min: 20 • max: 1600 • pattern: arn:\S+ Syntax: "string" "string" ...
    /// </summary>
    [CliOption("--structured-log-destinations", GroupValues = true)]
    public IEnumerable<string>? StructuredLogDestinations { get; set; }

    [CliOption("--cli-input-json")]
    public string? CliInputJson { get; set; }

    [CliOption("--generate-cli-skeleton")]
    public string? GenerateCliSkeleton { get; set; }

    /// <inheritdoc />
    IEnumerable<ValidationResult> IValidatableObject.Validate(ValidationContext validationContext)
    {
        if (_requiresAlternateInput && !(!string.IsNullOrWhiteSpace(CliInputJson) || GenerateCliSkeleton is "input" or "yaml-input"))
        {
            yield return new ValidationResult("An alternate input must remain selected for an instance created without required operation values.");
            yield break;
        }

        if (!string.IsNullOrWhiteSpace(CliInputJson) || GenerateCliSkeleton is "input" or "yaml-input")
        {
            yield break;
        }

        yield break;
    }

